mapper.update:
UPDATE tb_person_file
SET file_name = #{fileName}, file_size = #{fileSize}, file_data = #{fileData}, reg_dt = getdate()
WHERE person_id = #{personId} AND file_type = #{fileType};
IF @@ROWCOUNT = 0
  INSERT INTO tb_person_file (person_id, file_type, file_name, file_size, file_data)
  VALUES (#{personId}, #{fileType}, #{fileName}, #{fileSize}, #{fileData});

mapper.select:
SELECT person_id, file_type, file_name, file_size, file_data, reg_dt
FROM tb_person_file
WHERE person_id = #{personId} AND file_type = #{fileType}
